#define E183_EMBED_COMMON
#include "../../20261017_gt10_residual_comprehensive_v1/src/residual_tools.cpp"
#include <faiss/impl/ScalarQuantizer.h>
#include <faiss/utils/distances.h>
namespace e191 {
using namespace e183;
struct A {float distance;uint64_t arrival;int32_t id;};
struct Less {bool operator()(const A& a,const A& b)const{return a.distance<b.distance||(a.distance==b.distance&&a.arrival<b.arrival);}};
struct Stats {uint64_t scans=0,exact=0,blocks=0,pq=0,sq=0;std::vector<uint64_t> per_query;};
struct Backend {
 size_t N,d,M,sub;int metric;std::vector<int32_t> ids,idblock,hubtab,pool,scanned,sorted,candidates,mapped;std::vector<uint64_t> off;std::vector<float> centres,book,lut,values;std::vector<uint8_t> pqcodes,sqcodes;std::unordered_map<int32_t,size_t> hubslot;std::vector<std::pair<int,int>> freq;std::vector<std::pair<float,int>> ranked;std::vector<A> heap,all;std::vector<Posting::Record> merged;faiss::ScalarQuantizer quant;std::unique_ptr<faiss::ScalarQuantizer::SQDistanceComputer> sqdc;
 Backend(const json& c):N(c.at("base").at("n")),d(c.at("base").at("d")),M(c.at("PQ_M")),sub(d/M),metric(c.at("metric_id")),quant(d,faiss::ScalarQuantizer::QT_8bit){
  auto m=read_json(fs::path(c.at("models"))/"model.json");auto f=m.at("files");ids=read_raw<int32_t>(f.at("ids"));off=read_raw<uint64_t>(f.at("offsets"));centres=read_raw<float>(f.at("centres"));pqcodes=read_raw<uint8_t>(f.at("pq_codes"));book=read_raw<float>(f.at("book"));idblock=read_raw<int32_t>(f.at("id_block"));hubtab=read_raw<int32_t>(f.at("hub_blocks"));sqcodes=read_raw<uint8_t>(f.at("sq_codes"));quant.trained=read_raw<float>(f.at("sq_trained"));
  auto h=read_raw<int32_t>(c.at("router").at("ids"));for(size_t i=0;i<h.size();++i)hubslot[h[i]]=i;
  require(d%M==0&&ids.size()==N&&off.front()==0&&off.back()==N&&centres.size()==(off.size()-1)*d&&pqcodes.size()==N*M&&book.size()==M*256*sub&&idblock.size()==N&&hubtab.size()==h.size()*8&&sqcodes.size()==N*d&&quant.trained.size()==2*d,"E191 full layout");sqdc.reset(quant.get_distance_computer(faiss::MetricType(metric)));lut.resize(M*256);pool.reserve(32);scanned.reserve(32);sorted.reserve(100);candidates.reserve(96);mapped.reserve(100);freq.reserve(100);ranked.reserve(32);heap.reserve(96);all.reserve(2048);merged.reserve(196);values.reserve(96);
 }
 float score(const float*q,const float*x,size_t dim)const{return metric==1?faiss::fvec_L2sqr(q,x,dim):-faiss::fvec_inner_product(q,x,dim);}
 void proposals(const int32_t* R,size_t K,const int32_t*h,bool mainonly){pool.clear();scanned.clear();mapped.clear();for(size_t j=0;j<K;++j)mapped.push_back(idblock[R[j]]);std::sort(mapped.begin(),mapped.end());freq.clear();for(size_t i=0;i<mapped.size();){size_t j=i+1;while(j<mapped.size()&&mapped[j]==mapped[i])++j;freq.emplace_back(-int(j-i),mapped[i]);i=j;}std::sort(freq.begin(),freq.end());for(size_t j=0;j<std::min<size_t>(8,freq.size());++j)pool.push_back(freq[j].second);if(!mainonly)for(int j=0;j<3;++j){auto it=hubslot.find(h[j]);require(it!=hubslot.end(),"valid route label");for(size_t a=0;a<8;++a){int b=hubtab[it->second*8+a];if(b>=0)pool.push_back(b);}}std::sort(pool.begin(),pool.end());pool.erase(std::unique(pool.begin(),pool.end()),pool.end());require(!pool.empty()&&pool.size()<=32,"candidate pool bound");}
 void complete(faiss::DistanceComputer& dc,const float*q,int32_t*R,float*D,size_t K,const int32_t*h,const std::string&method,Stats& st,bool oracle=false){
  bool usepq=method=="REUSE-PQ";proposals(R,K,h,method=="MAIN-SQ");ranked.clear();for(int b:pool)ranked.emplace_back(score(q,centres.data()+size_t(b)*d,d),b);std::sort(ranked.begin(),ranked.end());st.blocks+=ranked.size();sorted.assign(R,R+K);std::sort(sorted.begin(),sorted.end());candidates.clear();heap.clear();all.clear();
  if(usepq)for(size_t m=0;m<M;++m)for(size_t z=0;z<256;++z)lut[m*256+z]=score(q+m*sub,book.data()+(m*256+z)*sub,sub);else sqdc->set_query(q);
  size_t consumed=0;uint64_t arrival=0;for(auto [dist,b]:ranked){size_t len=off[b+1]-off[b];if(consumed+len>2048)continue;scanned.push_back(b);for(size_t i=off[b];i<off[b+1];++i,++arrival){int32_t id=ids[i];if(std::binary_search(sorted.begin(),sorted.end(),id))continue;float v=0;if(usepq){for(size_t m=0;m<M;++m)v+=lut[m*256+pqcodes[i*M+m]];++st.pq;}else{v=sqdc->query_to_code(sqcodes.data()+i*d);if(metric==0)v=-v;++st.sq;}A a{v,arrival,id};if(oracle)all.push_back(a);else if(heap.size()<96){heap.push_back(a);std::push_heap(heap.begin(),heap.end(),Less{});}else if(Less{}(a,heap.front())){std::pop_heap(heap.begin(),heap.end(),Less{});heap.back()=a;std::push_heap(heap.begin(),heap.end(),Less{});}}
   consumed+=len;if(consumed==2048)break;
  }st.scans+=consumed;auto& selected=oracle?all:heap;std::sort(selected.begin(),selected.end(),Less{});if(selected.size()>96)selected.resize(96);for(auto a:selected)candidates.push_back(a.id);require(candidates.size()<=96&&consumed<=2048,"access / exact budget");values.clear();for(int id:candidates)values.push_back(dc(id));st.exact+=candidates.size();merged.clear();for(size_t j=0;j<K;++j)merged.push_back({R[j],D[j],uint32_t(j),false});
  if(oracle){for(size_t j=0;j<candidates.size();++j)merged.push_back({candidates[j],values[j],uint32_t(K+j),false});std::stable_sort(merged.begin(),merged.end(),Posting::better);merged.resize(K);}else{std::make_heap(merged.begin(),merged.end(),Posting::better);for(size_t j=0;j<candidates.size();++j)if(values[j]<merged.front().distance){std::pop_heap(merged.begin(),merged.end(),Posting::better);merged.back()={candidates[j],values[j],uint32_t(K+j),false};std::push_heap(merged.begin(),merged.end(),Posting::better);}std::sort(merged.begin(),merged.end(),Posting::better);}for(size_t j=0;j<K;++j){R[j]=merged[j].id;D[j]=merged[j].distance;}
 }
 size_t bytes()const{return ids.size()*4+idblock.size()*4+hubtab.size()*4+off.size()*8+centres.size()*4+book.size()*4+lut.size()*4+pqcodes.size()+sqcodes.size()+quant.trained.size()*4;}
};
void run(acsg::IndexACSGFlat& idx,const std::vector<float>&q,int L,const std::string&m,Router&r,Posting&p,Backend&e,Batch&b,Stats&st){
 if(m=="GT10"||m=="B32"){Method method;method.route=&r;method.family=m=="B32"?"POST":"GT10";if(m=="B32")method.table=&p;run_batch(idx,q,L,method,b);return;}
 idx.acsg.search_L=L;std::vector<std::vector<acsg::EnterPoint>> eps(b.n);for(size_t i=0;i<b.n;++i){auto v=r.route(q.data()+i*idx.d);for(int j=0;j<3;++j){b.entries[3*i+j]=v.ids[j];b.profile_distances[3*i+j]=v.distances[j];eps[i].emplace_back(v.ids[j],1.f);}}
 faiss::VisitedTable vt(idx.ntotal);std::unique_ptr<faiss::DistanceComputer>dc(acsg::storage_distance_computer(idx.storage));std::vector<acsg::Neighbor>ret;std::vector<faiss::idx_t>ids(b.k);std::vector<int32_t>cur(b.k);st.per_query.reserve(b.n*5);
 for(size_t i=0;i<b.n;++i){const float*qi=q.data()+i*idx.d;dc->set_query(qi);vt.advance();idx.acsg.search_new(*dc,b.k,ids.data(),b.distances.data()+i*b.k,vt,2,eps[i],&ret);for(size_t j=0;j<b.k;++j)cur[j]=ids[j];auto before=std::array<uint64_t,5>{st.scans,st.blocks,st.exact,st.pq,st.sq};e.complete(*dc,qi,cur.data(),b.distances.data()+i*b.k,b.k,b.entries.data()+3*i,m,st);std::copy(cur.begin(),cur.end(),b.ids.begin()+i*b.k);std::array<uint64_t,5>after{st.scans,st.blocks,st.exact,st.pq,st.sq};for(size_t j=0;j<5;++j)st.per_query.push_back(after[j]-before[j]);}
}
__attribute__((noinline)) double timed(acsg::IndexACSGFlat&idx,const std::vector<float>&q,int L,const std::string&m,Router&r,Posting&p,Backend&e,Batch&dest,Stats&st){auto t=Clock::now();{Batch out(dest.n,dest.k);run(idx,q,L,m,r,p,e,out,st);copy_packet(out,dest);asm volatile("" : : "g"(out.ids.data()),"g"(dest.ids.data()):"memory");}return seconds(t);}
json prepare_sq(const json&c){check_threads(c);auto t=Clock::now();fs::path out=c.at("models");auto model=read_json(out/"model.json");auto files=model.at("files");if(fs::exists(files.at("sq_codes").get<std::string>()))return {{"status","PASS_E191_SQ8_REUSED"},{"seconds",seconds(t)},{"codes",files.at("sq_codes")}};
 Matrix base(c.at("base"));auto x=base.copy();faiss::ScalarQuantizer sq(base.d,faiss::ScalarQuantizer::QT_8bit);sq.train(base.n,x.data());auto ids=read_raw<int32_t>(files.at("ids"));std::vector<uint8_t>codes(base.n*base.d),ordered(codes.size());sq.compute_codes(x.data(),codes.data(),base.n);for(size_t i=0;i<base.n;++i)std::copy(codes.begin()+size_t(ids[i])*base.d,codes.begin()+(size_t(ids[i])+1)*base.d,ordered.begin()+i*base.d);write_raw(files.at("sq_codes").get<std::string>(),ordered);write_raw(files.at("sq_trained").get<std::string>(),sq.trained);json rec={{"status","PASS_E191_SQ8_PREPARED"},{"N",base.n},{"d",base.d},{"code_bytes",ordered.size()},{"training","all original base, no query/GT"},{"threads",process_threads()},{"seconds",seconds(t)}};fresh_json(out/"sq8.json",rec);return rec;}
json benchmark(const json&c,bool qualify){check_threads(c);auto start=Clock::now();fs::path root=c.at("output_dir");fresh_dir(root);fresh_json(root/"config.json",c);json binding;auto idx=load_index(c,binding);Matrix qm(c.at("queries"));auto q=qm.copy();Router router(c.at("router"),idx->d,idx->ntotal);Posting post(c.at("table"),idx->ntotal);Backend aux(c);fresh_json(root/"environment.json",{{"threads",process_threads()},{"cpu",15},{"binding",binding},{"auxiliary_array_bytes",aux.bytes()},{"startup_seconds",seconds(start)},{"timer","complete allocation/init + route/main/completion + six-array copy + normal destruction"}});json results=json::array(),progress=json::array();size_t ordinal=0,batches=0;int repeats=qualify?1:3;
 for(auto it=c.at("K_L").begin();it!=c.at("K_L").end();++it){size_t K=std::stoul(it.key());std::set<int>cl;for(int L:c.at("completion_L").at(it.key()))cl.insert(L);for(int L:it.value()){
  require(L>=int(K),"true K budget");std::vector<std::string>methods={"GT10"};if(cl.count(L))methods=c.at("methods").get<std::vector<std::string>>();std::vector<std::unique_ptr<Batch>>first(methods.size());std::vector<json>rounds(methods.size(),json::array());std::vector<Stats>meters(methods.size());Batch archive(qm.n,K);
  for(int rep=0;rep<repeats;++rep)for(size_t off=0;off<methods.size();++off){size_t mi=(ordinal+rep+off)%methods.size();auto m=methods[mi];check_threads(c);fs::path point=root/("k"+std::to_string(K))/(m+"_L"+std::to_string(L));if(rep==0){Batch warm(std::min<size_t>(qm.n,256),K);Stats st;run(*idx,q,L,m,router,post,aux,warm,st);}Stats st;double wall=timed(*idx,q,L,m,router,post,aux,archive,st);++batches;check_threads(c);validate(archive,idx->ntotal);auto digest=packet_sha(archive);if(rep==0){first[mi]=std::make_unique<Batch>(archive);archive.save(point/"raw",false);meters[mi]=st;if(!st.per_query.empty())write_raw(point/"access.u64",st.per_query);}else all_same(*first[mi],archive);
   json v={{"round",rep},{"wall_seconds",wall},{"qps",qm.n/wall},{"packet_sha256",digest},{"threads",1},{"scanned_codes",st.scans},{"block_centres",st.blocks},{"extra_exact_scores",st.exact},{"PQ_scores",st.pq},{"SQ_scores",st.sq}};if(rep)require(digest==rounds[mi][0].at("packet_sha256"),"three-round SHA");rounds[mi].push_back(v);fresh_json(point/("round"+std::to_string(rep)+".json"),v);json ev={{"dataset",c.at("dataset")},{"K",K},{"L",L},{"method",m},{"round",rep},{"qps",qm.n/wall}};progress.push_back(ev);write_json(root/"progress.json",progress);std::cout<<ev.dump()<<std::endl;
  }
  if(cl.count(L)){require(methods[0]=="GT10","actual main first");std::unique_ptr<faiss::DistanceComputer>dc(acsg::storage_distance_computer(idx->storage));std::vector<int32_t>reuse_trace;
   for(size_t mi=1;mi<methods.size();++mi){auto m=methods[mi];if(m=="B32"){audit_merge(*idx,q,*first[0],*first[mi],post);continue;}std::vector<int32_t>trace(qm.n*160,-1);require(first[0]->entries==first[mi]->entries,"actual same route IDs");
    for(size_t i=0;i<qm.n;++i){std::vector<int32_t>rr(first[0]->ids.begin()+i*K,first[0]->ids.begin()+(i+1)*K);std::vector<float>dd(first[0]->distances.begin()+i*K,first[0]->distances.begin()+(i+1)*K);dc->set_query(q.data()+i*idx->d);Stats st;aux.complete(*dc,q.data()+i*idx->d,rr.data(),dd.data(),K,first[0]->entries.data()+3*i,m,st,true);for(size_t j=0;j<K;++j)require(rr[j]==first[mi]->ids[i*K+j]&&equal_float(dd[j],first[mi]->distances[i*K+j]),"full-sort candidate / merge oracle from actual main");std::copy(aux.pool.begin(),aux.pool.end(),trace.begin()+i*160);std::copy(aux.scanned.begin(),aux.scanned.end(),trace.begin()+i*160+32);std::copy(aux.candidates.begin(),aux.candidates.end(),trace.begin()+i*160+64);}
    if(m=="REUSE-PQ")reuse_trace=trace;else if(m=="REUSE-SQ"){require(reuse_trace.size()==trace.size(),"PQ before SQ");for(size_t i=0;i<qm.n;++i)for(size_t j=0;j<64;++j)require(reuse_trace[i*160+j]==trace[i*160+j],"all query pool / scan parity");}write_raw(root/("k"+std::to_string(K))/(m+"_L"+std::to_string(L))/"trace.i32",trace);
   }}
  for(size_t mi=0;mi<methods.size();++mi){std::vector<double>w;for(auto v:rounds[mi])w.push_back(v.at("wall_seconds"));std::sort(w.begin(),w.end());json rec={{"status","PASS_E191_POINT"},{"dataset",c.at("dataset")},{"method",methods[mi]},{"K",K},{"L",L},{"n",qm.n},{"qps",qm.n/w[w.size()/2]},{"rounds",rounds[mi]},{"timed_output_retained",true},{"all_round_bits_equal",true},{"result_dir",(root/("k"+std::to_string(K))/(methods[mi]+"_L"+std::to_string(L))).string()},{"scanned_codes_per_query",double(meters[mi].scans)/qm.n},{"block_centres_per_query",double(meters[mi].blocks)/qm.n},{"extra_exact_scores_per_query",double(meters[mi].exact)/qm.n},{"PQ_scores_per_query",double(meters[mi].pq)/qm.n},{"SQ_scores_per_query",double(meters[mi].sq)/qm.n}};fresh_json(fs::path(rec.at("result_dir"))/"result.json",rec);results.push_back(rec);}++ordinal;
 }}json rec={{"status",qualify?"PASS_E191_QUALIFICATION":"PASS_E191_MATRIX"},{"dataset",c.at("dataset")},{"points",results.size()},{"batches",batches},{"n",qm.n},{"results",results},{"outer_seconds",seconds(start)},{"evaluation_GT_read",false},{"threads",1}};fresh_json(root/"complete.json",rec);return rec;}
}
int main(int argc,char**argv){try{using namespace e191;require(argc==3,"mode config");auto c=read_json(argv[2]);std::string mode=argv[1];json r=mode=="prepare"?prepare_sq(c):benchmark(c,mode=="qualification");std::cout<<r.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"FATAL E191 "<<e.what()<<std::endl;return 2;}}
